import { DEFAULT_WORKERS } from './defaults.js';
export function resolveWorkers(env: Record<string, string | undefined>, profile: { workers?: number }, cli: { workers?: number }) {
  const base = Number(env.PREVIEW_WORKERS ?? DEFAULT_WORKERS);
  return cli.workers ?? profile.workers ?? base;
}

